package com.statseer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup("statseer")
public interface StatSeerConfig extends Config
{
	@ConfigItem(
		keyName = "hotkey",
		name = "Hotkey",
		description = "Hold this key while hovering an item to show equipment stats"
	)
	default Keybind hotkey()
	{
		return Keybind.NOT_SET;
	}
}

package com.statseer;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.plugins.itemstats.ItemStatOverlay;

class StatSeerOverlay extends ItemStatOverlay
{
	@Inject
	private StatSeerPlugin plugin;

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isInspecting())
		{
			return null;
		}

		return super.render(graphics);
	}
}

package com.statseer;

import com.google.inject.Binder;
import com.google.inject.PrivateModule;
import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.vars.InputType;
import net.runelite.client.config.Keybind;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.itemstats.ItemStatConfig;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Stat Seer",
	description = "Hold a hotkey while hovering items to show equipment stats",
	tags = {"item", "stats", "equipment", "gear", "hover", "compare"}
)
public class StatSeerPlugin extends Plugin
{
	private static final ItemStatConfig ITEM_STAT_CONFIG = new ItemStatConfig()
	{
		@Override
		public boolean consumableStats()
		{
			return false;
		}

		@Override
		public boolean equipmentStats()
		{
			return true;
		}

		@Override
		public boolean geStats()
		{
			return false;
		}
	};

	@Inject
	private Client client;

	@Inject
	private StatSeerConfig config;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private StatSeerOverlay overlay;

	private boolean hotkeyDown;

	private final KeyListener hotkeyListener = new KeyListener()
	{
		@Override
		public void keyTyped(KeyEvent event)
		{
		}

		@Override
		public void keyPressed(KeyEvent event)
		{
			final Keybind hotkey = config.hotkey();
			if (!hotkey.matches(event))
			{
				return;
			}

			if (isTyping())
			{
				hotkeyDown = false;
				return;
			}

			if (hotkeyDown)
			{
				return;
			}

			hotkeyDown = true;
		}

		@Override
		public void keyReleased(KeyEvent event)
		{
			if (config.hotkey().matches(event))
			{
				hotkeyDown = false;
			}
		}

		@Override
		public void focusLost()
		{
			hotkeyDown = false;
		}
	};

	@Override
	public void configure(Binder binder)
	{
		binder.install(new PrivateModule()
		{
			@Override
			protected void configure()
			{
				bind(ItemStatConfig.class).toInstance(ITEM_STAT_CONFIG);
				bind(StatSeerOverlay.class);
				expose(StatSeerOverlay.class);
			}
		});
	}

	@Override
	protected void startUp()
	{
		keyManager.registerKeyListener(hotkeyListener);
		overlayManager.add(overlay);
		log.debug("Stat Seer started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		keyManager.unregisterKeyListener(hotkeyListener);
		hotkeyDown = false;
		log.debug("Stat Seer stopped");
	}

	boolean isInspecting()
	{
		return hotkeyDown && !isTyping();
	}

	private boolean isTyping()
	{
		final int inputType = client.getVarcIntValue(VarClientID.MESLAYERMODE);
		return client.getFocusedInputFieldWidget() != null
			|| client.getVarcIntValue(VarClientID.WORLDMAP_SEARCHING) != 0
			|| inputType != InputType.NONE.getType()
			|| hasText(client.getVarcStrValue(VarClientID.CHATINPUT));
	}

	private static boolean hasText(String value)
	{
		return value != null && !value.isEmpty();
	}

	@Provides
	StatSeerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(StatSeerConfig.class);
	}
}

package com.statseer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class StatSeerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(StatSeerPlugin.class);
		RuneLite.main(args);
	}
}
